style.css:
/* Universal black background for all websites */
body {
    background-color: black !important; /* Black background */
    color: white !important; /* White text for readability */
}

header, footer, div, section {
    background-color: black !important; /* Ensures all sections are black */
    color: white !important; /* Ensures all text is visible */
}

a {
    color: #00bfff !important; /* Light blue for links */
}

a:visited {
    color: #ff69b4 !important; /* Pink for visited links */
}
